// Priority queue for open set (min-heap based on f_score)
using OpenSet = std::priority_queue<
    std::pair<int, std::shared_ptr<Node>>,
    std::vector<std::pair<int, std::shared_ptr<Node>>>,
    std::greater<std::pair<int, std::shared_ptr<Node>>>>;

// Get node with lowest f_score from open set
auto get_node = [&open_set]() {
    auto node_pair = open_set.top();
    open_set.pop();
    return node_pair.second;
};

// Heuristic function (Euclidean distance for this example)
auto heuristic = [](const std::shared_ptr<Node>& a, const std::shared_ptr<Node>& b) {
    double dx = a->x - b->x;
    double dy = a->y - b->y;
    return std::sqrt(dx*dx + dy*dy);
};

// Initialize data structures
std::unordered_map<int, std::shared_ptr<Node>> came_from;
std::unordered_map<int, double> g_score;
std::unordered_map<int, double> f_score;
OpenSet open_set;

// Set initial node
auto start_node = std::make_shared<Node>(graph.nodes[start_idx]);
g_score[start_idx] = 0.0;
f_score[start_idx] = heuristic(start_node, std::make_shared<Node>(graph.nodes[end_idx]));
open_set.push({static_cast<int>(f_score[start_idx]), start_node});

// Main A* loop
while (!open_set.empty()) {
    auto current = get_node();
    int current_idx = current->index;

    // Check if we've reached the end
    if (current_idx == end_idx) {
        // Reconstruct path
        std::vector<std::shared_ptr<Node>> path;
        while (came_from.find(current_idx) != came_from.end()) {
            path.push_back(current);
            current = came_from[current_idx];
        }
        path.push_back(current);

        // Convert to vector<Node> and reverse
        std::vector<Node> result;
        for (auto it = path.rbegin(); it != path.rend(); ++it) {
            result.push_back(**it);
        }
        return result;
    }

    // Explore neighbors
    for (const auto& neighbor_idx : graph.adjacency_list[current_idx]) {
        auto neighbor = std::make_shared<Node>(graph.nodes[neighbor_idx]);
        auto tentative_g_score = g_score[current_idx] + graph.get_edge_weight(current_idx, neighbor_idx);

        if (g_score.find(neighbor_idx) == g_score.end() || tentative_g_score < g_score[neighbor_idx]) {
            came_from[neighbor_idx] = current;
            g_score[neighbor_idx] = tentative_g_score;
            f_score[neighbor_idx] = tentative_g_score + heuristic(neighbor, std::make_shared<Node>(graph.nodes[end_idx]));

            if (g_score.find(neighbor_idx) == g_score.end()) {
                open_set.push({static_cast<int>(f_score[neighbor_idx]), neighbor});
            }
        }
    }
}

return {}; // Return empty path if no route found
// END_CODE

